import sys
from math import gcd

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    m = int(data[0])
    s = []
    for k in range(1, m + 1):
        s.append(int(data[k]))

    s_set = set(s)

    if len(s) > 1 and gcd(s[0], s[1]) not in s_set:
        print("-1")
        return

    ans = []
    for x in s:
        ans.append(x)
        ans.append(x)

    n = len(ans)
    computed_gcds = set()
    for i in range(n):
        g = 0
        for j in range(i, n):
            if g == 0:
                g = ans[j]
            else:
                g = gcd(g, ans[j])
            computed_gcds.add(g)

    if computed_gcds != s_set:
        print("-1")
    else:
        print(n)
        print(" ".join(map(str, ans)))

if __name__ == "__main__":
    main()
